// Gate tests G2 to G8: the module's core must match the expected results in fixtures/expected.
// Written before any module code exists. Do not edit this file; if a test looks wrong,
// record it as disputed in docs/report.md and leave it as it is.
import { describe, expect, test } from 'vitest';
import { readFileSync, readdirSync } from 'node:fs';
import * as core from '../../module/core';

type Key = string | number;
const FIXTURES = new URL('../../fixtures/', import.meta.url);
const read = (rel: string) => JSON.parse(readFileSync(new URL(rel, FIXTURES), 'utf8'));
const names = readdirSync(new URL('graphs/', FIXTURES))
  .filter((f) => f.endsWith('.json'))
  .map((f) => f.replace(/\.json$/, ''))
  .sort();

// compare lists of keys or paths as sets, so that order within them does not matter
const asSet = (items: unknown[]) => items.map((x) => JSON.stringify(x)).sort();

function loaded(name: string) {
  const result = core.loadGraph(read(`graphs/${name}.json`));
  if (!result.ok) throw new Error(`${name} was refused: ${result.code}`);
  return result;
}

test('G0 the fixture set is complete', () => {
  expect(names.length).toBe(27);
});

describe('G2 loading and issues', () => {
  for (const name of names) {
    test(name, () => {
      const exp = read(`expected/${name}.json`);
      const result = core.loadGraph(read(`graphs/${name}.json`));
      if (exp.load === 'refused') {
        expect(result.ok).toBe(false);
        if (!result.ok) expect(result.code).toBe(exp.code);
        return;
      }
      expect(result.ok).toBe(true);
      if (!result.ok) return;
      expect(result.issues).toEqual(exp.issues);
      expect(result.graph.units.length).toBe(exp.counts.units);
      expect(result.graph.keypairs.length).toBe(exp.counts.keypairs);
      expect(core.relationCount(result.graph)).toBe(exp.counts.relations);
    });
  }
});

describe('G3 fingerprints of the stored and the current graph', () => {
  for (const name of names) {
    const exp = read(`expected/${name}.json`);
    if (exp.load !== 'ok') continue;
    test(name, async () => {
      const { graph } = loaded(name);
      // fingerprint() may return the text or a promise of it
      expect(await core.fingerprint(graph)).toBe(exp.fingerprint.stored);
      expect(await core.fingerprint(core.currentGraph(graph))).toBe(exp.fingerprint.current);
    });
  }
});

describe('G4 components', () => {
  for (const name of names) {
    const exp = read(`expected/${name}.json`);
    if (exp.load !== 'ok') continue;
    test(name, () => {
      const { graph } = loaded(name);
      expect(core.components(graph).sizes).toEqual(exp.components.stored);
      expect(core.components(core.currentGraph(graph)).sizes).toEqual(exp.components.current);
      if (exp.counts.current) {
        const cur = core.currentGraph(graph);
        expect(cur.units.length).toBe(exp.counts.current.units);
        expect(cur.keypairs.length).toBe(exp.counts.current.keypairs);
        expect(core.relationCount(cur)).toBe(exp.counts.current.relations);
      }
    });
  }
});

describe('G5 degrees', () => {
  for (const name of names) {
    const exp = read(`expected/${name}.json`);
    if (!exp.degrees) continue;
    test(name, () => {
      const { graph } = loaded(name);
      expect(core.degrees(graph)).toEqual(exp.degrees);
    });
  }
});

describe('G6 rings', () => {
  for (const name of names) {
    const exp = read(`expected/${name}.json`);
    if (!exp.rings) continue;
    for (const entry of exp.rings) {
      test(`${name}, focus ${JSON.stringify(entry.focus)}, ${entry.graph} graph`, () => {
        const { graph } = loaded(name);
        const g = entry.graph === 'current' ? core.currentGraph(graph) : graph;
        const got = core.rings(g, entry.focus as Key);
        if (entry.ringSizes) {
          expect(got.rings.map((r: Key[]) => r.length)).toEqual(entry.ringSizes);
          expect(got.beyond.length).toBe(entry.beyond);
          return;
        }
        expect(got.rings.map((r: Key[]) => asSet(r))).toEqual(entry.rings.map((r: Key[]) => asSet(r)));
        expect(asSet(got.beyond)).toEqual(asSet(entry.beyond));
      });
    }
  }
});

describe('G7 path sets', () => {
  for (const name of names) {
    const exp = read(`expected/${name}.json`);
    if (!exp.paths) continue;
    for (const entry of exp.paths) {
      const label = `${name}: ${JSON.stringify(entry.from)} to ${JSON.stringify(entry.to)}, ` +
        `${entry.extra} extra, limit ${entry.countLimit}, ${entry.graph} graph`;
      test(label, () => {
        const { graph } = loaded(name);
        const g = entry.graph === 'current' ? core.currentGraph(graph) : graph;
        const got = core.pathSet(g, entry.from, entry.to, entry.extra,
          { count: entry.countLimit, list: entry.listLimit, timeMs: 60000 });
        expect(got.shortest).toBe(entry.shortest);
        expect(got.reason).toBe(entry.reason);
        expect(got.stopped).toBe(entry.stopped);
        expect(got.total).toBe(entry.total);
        expect(got.lengths.map((l: { length: number; count: number; exact: boolean }) =>
          ({ length: l.length, count: l.count, exact: l.exact })))
          .toEqual(entry.lengths.map((l: { length: number; count: number; exact: boolean }) =>
            ({ length: l.length, count: l.count, exact: l.exact })));
        entry.lengths.forEach((l: { paths?: Key[][] }, i: number) => {
          if (l.paths) expect(asSet(got.lengths[i].paths)).toEqual(asSet(l.paths));
        });
      });
    }
  }
});

test('G8 database graph: 2,628 of 3,240 pairs have exactly one path within two extra steps', () => {
  const exp = read('expected/database-2026-07-24.json');
  const { graph } = loaded('database-2026-07-24');
  const units = graph.units;
  let pairs = 0;
  let one = 0;
  for (let i = 0; i < units.length; i++) {
    for (let j = i + 1; j < units.length; j++) {
      pairs++;
      if (core.pathSet(graph, units[i], units[j], 2, { timeMs: 60000 }).total === 1) one++;
    }
  }
  expect(pairs).toBe(exp.summary.unorderedPairs);
  expect(one).toBe(exp.summary.pairsWithExactlyOnePathWithinTwoExtraSteps);
});

test('G7 default limits: counting stops at 10,000 paths', () => {
  const { graph } = loaded('complete-9');
  const got = core.pathSet(graph, 1, 2, 7);
  expect(got.stopped).toBe(true);
  expect(got.stoppedBy).toBe('count');
  expect(got.total).toBe(10000);
  expect(got.lengths[got.lengths.length - 1]).toMatchObject({ length: 8, count: 1340, exact: false });
  for (const l of got.lengths) expect(l.paths.length).toBeLessThanOrEqual(200);
});
